#!/usr/bin/python3
"""Generate param/nav2_params.yaml for the Kobuki TurtleBot2 from the stock Nav2 Jazzy params.

Run once and commit the result; the generated file is the thing you edit afterwards:
  /usr/bin/python3 scripts/gen_nav2_params.py > param/nav2_params.yaml
Every change relative to the stock file is a numbered patch below, so the diff is auditable.
"""
import copy
import sys

import yaml

STOCK = '/opt/ros/jazzy/share/nav2_bringup/params/nav2_params.yaml'
HEADER = """\
# Nav2 parameters for the Kobuki TurtleBot2 (frames: map -> odom -> base, scan on /scan).
# GENERATED by scripts/gen_nav2_params.py from the stock Nav2 Jazzy params, then meant to be
# edited by hand. Launch: navigation.launch.py. Nav2's final output goes to `nav2/cmd_vel`,
# which cmd_vel_mux_node (extensions.launch.py) clamps and forwards to the robot.
#
# Things you probably want to measure/tune on the real robot:
#   robot_radius (0.18 m is a guess for the Kobuki), laser_max_range, controller speeds,
#   FollowPath.desired_linear_vel, velocity_smoother limits, obstacle ranges.
# Depth obstacles: set  observation_sources: scan depth_scan  in both costmaps and start
# sensors.launch.py with depth_scan:=true (RealSense -> depthimage_to_laserscan -> /depth_scan).
"""


def patch(p):
    p = copy.deepcopy(p)
    # 1. only the nodes we launch; route/docking servers and the loopback sim are not used
    for k in ('route_server', 'docking_server', 'loopback_simulator'):
        p.pop(k, None)

    # 2. frames: the Kobuki driver publishes odom -> base (not base_link / base_footprint)
    p['amcl']['ros__parameters']['base_frame_id'] = 'base'
    p['bt_navigator']['ros__parameters']['robot_base_frame'] = 'base'
    p['bt_navigator']['ros__parameters']['odom_topic'] = 'odom'
    p['behavior_server']['ros__parameters']['robot_base_frame'] = 'base'
    p['collision_monitor']['ros__parameters']['base_frame_id'] = 'base'
    for cm in ('local_costmap', 'global_costmap'):
        p[cm][cm]['ros__parameters']['robot_base_frame'] = 'base'

    # 3. AMCL for an RPLIDAR A1 (12 m, ~360 beams)
    a = p['amcl']['ros__parameters']
    a.update(laser_max_range=12.0, laser_min_range=0.15, max_beams=60, update_min_d=0.1,
             update_min_a=0.1, set_initial_pose=False, scan_topic='scan')
    a['initial_pose'] = {'x': 0.0, 'y': 0.0, 'z': 0.0, 'yaw': 0.0}

    # 4. light controller for a Pi/Jetson: Regulated Pure Pursuit behind a rotation shim
    c = p['controller_server']['ros__parameters']
    c['controller_frequency'] = 20.0
    c['goal_checker_plugins'] = ['general_goal_checker']
    c['general_goal_checker'].update(xy_goal_tolerance=0.15, yaw_goal_tolerance=0.25)
    c['progress_checker'].update(required_movement_radius=0.3, movement_time_allowance=15.0)
    c['FollowPath'] = {
        'plugin': 'nav2_rotation_shim_controller::RotationShimController',
        'primary_controller':
            'nav2_regulated_pure_pursuit_controller::RegulatedPurePursuitController',
        'angular_dist_threshold': 0.785,
        'forward_sampling_distance': 0.5,
        'rotate_to_heading_angular_vel': 0.8,
        'max_angular_accel': 2.0,
        'simulate_ahead_time': 1.0,
        'rotate_to_goal_heading': False,
        # --- RegulatedPurePursuit (nested under the shim) ---
        'desired_linear_vel': 0.25,
        'lookahead_dist': 0.5,
        'min_lookahead_dist': 0.3,
        'max_lookahead_dist': 0.9,
        'lookahead_time': 1.5,
        'transform_tolerance': 0.2,
        'use_velocity_scaled_lookahead_dist': True,
        'min_approach_linear_velocity': 0.05,
        'approach_velocity_scaling_dist': 0.6,
        'use_collision_detection': True,
        'max_allowed_time_to_collision_up_to_carrot': 1.0,
        'use_regulated_linear_velocity_scaling': True,
        'regulated_linear_scaling_min_radius': 0.6,
        'regulated_linear_scaling_min_speed': 0.1,
        'use_cost_regulated_linear_velocity_scaling': True,
        'cost_scaling_dist': 0.5,
        'cost_scaling_gain': 1.0,
        'allow_reversing': False,
        'use_rotate_to_heading': True,
        'rotate_to_heading_min_angle': 0.785,
        'max_robot_pose_search_dist': 1.5,
    }

    # 5. conservative speeds (the mux clamps again at max_linear/max_angular)
    v = p['velocity_smoother']['ros__parameters']
    v.update(max_velocity=[0.3, 0.0, 1.0], min_velocity=[-0.15, 0.0, -1.0],
             max_accel=[1.0, 0.0, 2.5], max_decel=[-1.0, 0.0, -2.5], odom_topic='odom')

    # 6. costmaps: circle footprint, 2D obstacle layer (cheaper than voxel), optional depth scan
    scan = {'topic': '/scan', 'max_obstacle_height': 2.0, 'clearing': True, 'marking': True,
            'data_type': 'LaserScan', 'raytrace_max_range': 4.0, 'raytrace_min_range': 0.0,
            'obstacle_max_range': 3.0, 'obstacle_min_range': 0.0}
    depth = dict(scan, topic='/depth_scan', raytrace_max_range=3.0, obstacle_max_range=2.5)
    lc = p['local_costmap']['local_costmap']['ros__parameters']
    lc.update(robot_radius=0.18, plugins=['obstacle_layer', 'inflation_layer'])
    lc.pop('voxel_layer', None)
    lc['obstacle_layer'] = {'plugin': 'nav2_costmap_2d::ObstacleLayer', 'enabled': True,
                            'observation_sources': 'scan', 'scan': dict(scan),
                            'depth_scan': dict(depth)}
    lc['inflation_layer'].update(cost_scaling_factor=3.0, inflation_radius=0.45)
    gc = p['global_costmap']['global_costmap']['ros__parameters']
    gc.update(robot_radius=0.18)
    gc['obstacle_layer'] = {'plugin': 'nav2_costmap_2d::ObstacleLayer', 'enabled': True,
                            'observation_sources': 'scan', 'scan': dict(scan),
                            'depth_scan': dict(depth)}
    gc['inflation_layer'].update(cost_scaling_factor=3.0, inflation_radius=0.45)

    # 7. planner: do not plan through unknown space (flip to true when exploring)
    p['planner_server']['ros__parameters']['GridBased']['allow_unknown'] = False

    # 8. collision monitor: output goes to the safety mux, not straight to the wheels
    m = p['collision_monitor']['ros__parameters']
    m['cmd_vel_out_topic'] = 'nav2/cmd_vel'
    # min_height 0.15 would silently drop every scan point if the lidar sits below 15 cm
    m['scan']['min_height'] = 0.0
    return p


class _Dumper(yaml.SafeDumper):
    pass


def _list(dumper, data):
    flow = all(isinstance(x, (int, float, str, bool)) for x in data) and len(data) <= 8
    return dumper.represent_sequence('tag:yaml.org,2002:seq', data, flow_style=flow)


_Dumper.add_representer(list, _list)


def main():
    with open(STOCK) as f:
        stock = yaml.safe_load(f)
    sys.stdout.write(HEADER)
    yaml.dump(patch(stock), sys.stdout, Dumper=_Dumper, sort_keys=False,
              default_flow_style=False, width=100)


if __name__ == '__main__':
    main()
